css:
body { font-family: system-ui, sans-serif; margin: 0; }
header { padding: 1rem; background: #164f3b; display: flex; justify-content: space-between; align-items: center; }
header a { color: white; text-decoration: none; }
.logo { font-size: 1.5rem; font-weight: bold; }
nav { display: flex; gap: 1rem; }
.hero { padding: 2rem; background: #f4f1e8; min-height: 220px; display: flex; flex-direction: column; align-items: center; justify-content: center; }
.button { background: #164f3b; color: white; padding: 0.6rem 1rem; border-radius: 6px; text-decoration: none; }
